{
  "candidates": [
    {
      "sequence": "SVQYNGQTVS",
      "hypothesis": "Shape-led, 10 aa: a compact, polar-edged turn could present Y/V toward V48–V52 and H50. Untested prediction; no first-round evidence was supplied.",
      "expected_discrimination": "Favor the MSA compact neighborhood: V48–A76 is 5.3–9.8 Å versus 30.4 Å in 8A9L; 6CU7 largely buries V48–V52."
    },
    {
      "sequence": "KSVQYPGQTVSE",
      "hypothesis": "Shape-led, 12 aa: PG constrains a turn while terminal charges limit hydrophobic aggregation; Y could contact H50.",
      "expected_discrimination": "Test fit to the MSA H50/G51 surface and compact 76-region rim, not direct binding to buried A76; 8A9L separates that rim and 6CU7 occludes the core."
    },
    {
      "sequence": "ESVYNGSTVQGSK",
      "hypothesis": "Shape-led, 13 aa: an NG-containing flexible bend could accommodate all three MSA geometries without requiring exposed A53.",
      "expected_discrimination": "A53 exposure differs sharply across MSA, so prioritize V48–H50; 8A9L lacks nearby A76/A78, while 6CU7 buries V48/V49."
    },
    {
      "sequence": "KTVQYSGPGSQVTE",
      "hypothesis": "Shape-led, 14 aa: a GPG hinge separates two small hydrophobic contact faces for the compact MSA neighborhood.",
      "expected_discrimination": "V48–A78 spans 5.4–8.2 Å in MSA versus 32.9 Å in 8A9L; similar geometry in 6CU7 is countered by near-zero anchor SASA."
    },
    {
      "sequence": "ESQVTYNGSQTVPGQSK",
      "hypothesis": "Shape-led, 17 aa: two turn-capable segments test adaptable rim binding while avoiding an extended hydrophobic strand.",
      "expected_discrimination": "Flexibility may tolerate H50–A78 distances of 9.4–14.5 Å across MSA; 8A9L gives 37.0 Å and 6CU7 offers little exposed surface."
    },
    {
      "sequence": "EVQYDSQTVK",
      "hypothesis": "Charge-led, 10 aa: D/E near Y could provide hydrogen bonding or pH-dependent electrostatic recognition of H50.",
      "expected_discrimination": "H50 alone cannot distinguish exposed 8A9L; selectivity must also require the compact MSA rim. 6CU7 H50 SASA is only 14.7 Å²."
    },
    {
      "sequence": "KSVYEGDNTVQE",
      "hypothesis": "Charge-led, 12 aa: adjacent acidic groups test alternative orientations toward H50, with V/Y providing modest hydrophobic anchoring.",
      "expected_discrimination": "Seek cooperative H50 and V48/V49 contacts in MSA plus compact-rim shape recognition; neither H50 charge recognition nor hydrophobicity alone excludes 8A9L."
    },
    {
      "sequence": "DSQYVNGTEVQSK",
      "hypothesis": "Charge-led, 13 aa: separated D/E groups and an NG turn probe a solvent-facing acidic cap around accessible MSA H50.",
      "expected_discrimination": "MSA H50 SASA is 86.4–92.4 Å²; 6CU7 is much lower. Reject models also fitting the spatially separated 8A9L 48/76 neighborhood."
    },
    {
      "sequence": "EQTVDYSGQTVNSEK",
      "hypothesis": "Charge-led, 15 aa: a mildly anionic, flexible peptide tests H50 polar contacts with interrupted V/Y hydrophobic contacts.",
      "expected_discrimination": "Depend on exposed V48–V52 plus the compact MSA contour; 8A9L is more exposed but has V49–A76 at 30.1 Å versus 5.9–7.0 Å in MSA."
    },
    {
      "sequence": "KSEVQYDGSTVQENSGTK",
      "hypothesis": "Charge-led, 18 aa: distributed charges test a soluble extended-rim binder rather than a strongly acidic H50-only ligand.",
      "expected_discrimination": "Prediction should preserve contacts across all MSA models despite A53/A76 exposure changes; 8A9L lacks the compact rim and 6CU7 buries most anchors."
    },
    {
      "sequence": "NQSYVTGQSN",
      "hypothesis": "Polar-led, 10 aa: N/Q/S side chains could complement H50 and backbone groups around G51, with one Y/V contact pair.",
      "expected_discrimination": "Core chemistry is shared with controls; require compact MSA shape complementarity to reject 8A9L and accessible anchors to reject 6CU7."
    },
    {
      "sequence": "SQNYVSGTQNSK",
      "hypothesis": "Polar-led, 12 aa: a flexible polar scaffold tests hydrogen-bond-rich binding without dependence on histidine protonation.",
      "expected_discrimination": "Target exposed MSA H50/G51 while sensing the nearby 76-region contour; 8A9L places H50–A76 at 33.6 Å versus 9.4–9.7 Å in MSA."
    },
    {
      "sequence": "KQNVTYSGNQTVSE",
      "hypothesis": "Polar-led, 14 aa: alternating polar and modest hydrophobic residues test a shallow interface along V48–V52.",
      "expected_discrimination": "Local 48–52 distances alone are similar across classes; require additional compact-rim contacts for 8A9L discrimination and accessibility for 6CU7 discrimination."
    },
    {
      "sequence": "ESQNYVGTNSQTVQSK",
      "hypothesis": "Polar-led, 16 aa: multiple hydrogen-bond donors/acceptors could tolerate MSA contour variation while a Y/V pair anchors near H50.",
      "expected_discrimination": "Avoid obligatory A53/A76 side-chain contacts because their MSA SASA varies; test surrounding contour recognition absent in 8A9L and occluded in 6CU7."
    },
    {
      "sequence": "KSTNQYVSGTQNSVQGSETQSK",
      "hypothesis": "Polar-led, 22 aa: a longer, hydrophilic alternative tests adaptable multivalent rim contacts; no cysteine or long hydrophobic run.",
      "expected_discrimination": "Require compact binding across MSA rather than nonspecific extended adsorption to 8A9L; 6CU7 should weaken binding through burial. Assembly layer-count differences limit SASA-based inference."
    }
  ]
}
